package dev.tiertagger.client;
import dev.tiertagger.core.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.ClientGameTestContext;
import net.minecraft.client.Minecraft;
import net.minecraft.client.KeyMapping;
import net.minecraft.client.input.KeyEvent;
import net.minecraft.client.gui.components.*;
import com.mojang.blaze3d.platform.InputConstants;
import com.mojang.authlib.GameProfile;
import net.minecraft.client.player.RemotePlayer;
import net.minecraft.client.multiplayer.PlayerInfo;
import java.util.*;import java.util.concurrent.atomic.*;
import com.sun.net.httpserver.HttpServer;
public final class PolishTest {
 private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 @SuppressWarnings("unchecked") private static Map<UUID,PlayerInfo> infos(Minecraft client){try{var field=client.getConnection().getClass().getDeclaredField("playerInfoMap");field.setAccessible(true);return (Map<UUID,PlayerInfo>)field.get(client.getConnection());}catch(Exception e){throw new AssertionError(e);}}
 private static RemotePlayer add(Minecraft client,UUID id,String name,int entity,double dx,double dy,boolean listed){var profile=new GameProfile(id,name);if(listed)infos(client).put(id,new PlayerInfo(profile,false));var player=new RemotePlayer(client.level,profile);player.setId(entity);player.setPos(client.player.getX()+dx,client.player.getY()+dy,client.player.getZ());client.level.addEntity(player);return player;}
 private static void press(Minecraft client){KeyMapping.click(NearestProfile.key.getDefaultKey());}
 public static void run(ClientGameTestContext context){
  UUID near=UUID.fromString("11111111-1111-4111-8111-111111111111"),far=UUID.fromString("22222222-2222-4222-8222-222222222222"),fake=UUID.fromString("33333333-3333-4333-8333-333333333333");
  var oldResolver=RestrictionChecks.identities;var oldRanks=TierTagger.ranks;var oldConfig=TierTagger.config;AtomicInteger requests=new AtomicInteger(),identities=new AtomicInteger();AtomicBoolean mismatch=new AtomicBoolean();RemotePlayer[] players=new RemotePlayer[3];String[] clipboard={""};
  HttpServer server;try{server=HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);}catch(Exception e){throw new AssertionError(e);}
  server.createContext("/",exchange->{identities.incrementAndGet();try{Thread.sleep(150);}catch(InterruptedException e){Thread.currentThread().interrupt();}String name=exchange.getRequestURI().getPath().substring(1);byte[] bytes=("{\"id\":\""+(mismatch.get()||name.equals("FarFixture")?far:near).toString().replace("-","")+"\",\"name\":\""+name+"\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);exchange.close();});server.start();
  java.net.URI base=java.net.URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/");
  try(var resolver=new MinecraftIdentityResolver(base)){
   context.runOnClient(client->{clipboard[0]=client.keyboardHandler.getClipboard();RestrictionChecks.identities=resolver;TierTagger.config=new Preferences();TierTagger.config.setupComplete=true;TierTagger.config.enabled=false;TierTagger.ranks=new ProviderRegistry(List.of(new RankingProvider(){public String id(){return "mctiers";}public Optional<String> tier(UUID id,String mode){return mode.equals("sword")||mode.equals("crystal")?Optional.of("HT3"):Optional.empty();}public boolean resolved(UUID id){return true;}public void request(UUID id){requests.incrementAndGet();}public String status(){return "Connected";}public void clear(){}public void close(){}}));players[0]=add(client,near,"NearFixture",200001,3,0,true);players[1]=add(client,far,"FarFixture",200002,1,8,true);players[2]=add(client,fake,"FakeFixture",200003,1,0,false);check(NearestProfile.nearest(client).orElseThrow().uuid().equals(near),"nearest selection uses 3D distance, excludes self and unlisted NPC");check(NearestProfile.key.getDefaultKey().getValue()==InputConstants.KEY_P,"P is the default key");client.setScreenAndShow(null);press(client);});
   context.waitFor(client->Platform.screen(client) instanceof SettingsScreen screen&&screen.page==3);
   context.runOnClient(client->{players[0].setPos(client.player.getX()+100,client.player.getY(),client.player.getZ());var screen=(SettingsScreen)Platform.screen(client);check(screen.drawLabels().stream().anyMatch(l->l.text().getString().contains("NearFixture")&&l.text().getString().contains("3.0 blocks at selection")),"target header shows immutable name and distance");});
   context.waitFor(client->requests.get()>0);context.waitTicks(3);context.takeScreenshot("nearest-profile");
   context.runOnClient(client->{check(Platform.screen(client) instanceof SettingsScreen,"vanilla Social Interactions did not replace tier profile");press(client);});context.waitTicks(3);context.runOnClient(client->check(Platform.screen(client) instanceof SettingsScreen,"repeated P while in profile stays in same menu"));
   context.runOnClient(client->{var screen=(SettingsScreen)Platform.screen(client);var heading=screen.drawLabels().stream().filter(l->l.text().getString().equals("McTiers")).findFirst().orElseThrow();var click=new net.minecraft.client.input.MouseButtonEvent(heading.x()+2,heading.y()+2,new net.minecraft.client.input.MouseButtonInfo(com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_LEFT,0));check(screen.mouseClicked(click,false),"provider heading is clickable");check(screen.drawLabels().stream().anyMatch(l->l.text().getString().contains("collapsed")),"heading click collapses provider");check(screen.mouseClicked(click,false),"heading click expands again");});
   context.clickScreenButton("Profile actions");context.clickScreenButton("Copy username");context.runOnClient(client->check(client.keyboardHandler.getClipboard().equals("NearFixture"),"copy resolved username"));context.clickScreenButton("Copy UUID");context.runOnClient(client->check(client.keyboardHandler.getClipboard().equals(near.toString()),"copy premium UUID"));context.clickScreenButton("Collapse all");context.runOnClient(client->check(((SettingsScreen)Platform.screen(client)).drawLabels().stream().noneMatch(l->l.text().getString().contains("Sword  HT3")),"collapse removes child tier rows"));context.waitTicks(3);context.takeScreenshot("profile-collapsed");context.clickScreenButton("Profile actions");context.clickScreenButton("Expand all");context.runOnClient(client->check(((SettingsScreen)Platform.screen(client)).drawLabels().stream().anyMatch(l->l.text().getString().contains("Sword  HT3")),"expand restores tier rows"));
   context.clickScreenButton("Info");context.clickScreenButton("McTiers");context.clickScreenButton("Report a problem");context.clickScreenButton("Copy report");context.runOnClient(client->{String report=client.keyboardHandler.getClipboard();check(report.contains("Minecraft:")&&report.contains("Provider: McTiers")&&report.contains("Fabric API:"),"provider report includes useful version and error details");});context.waitTicks(3);context.takeScreenshot("provider-report");context.clickScreenButton("Back");context.clickScreenButton("Info");context.clickScreenButton("Why is a tier missing?");context.waitTicks(3);context.takeScreenshot("missing-tier-help");
   context.clickScreenButton("Main");context.clickScreenButton("Crystal");context.runOnClient(client->{var screen=(SettingsScreen)Platform.screen(client);var field=(EditBox)screen.children().stream().filter(c->c instanceof EditBox).findFirst().orElseThrow();field.setValue("Vanilla");});context.waitTicks(3);context.runOnClient(client->{var screen=(SettingsScreen)Platform.screen(client);check(screen.children().stream().filter(c->c instanceof AbstractWidget).map(c->((AbstractWidget)c).getMessage().getString()).anyMatch("Crystal"::equals),"Vanilla search finds Crystal");});context.waitTicks(3);context.takeScreenshot("alias-search");
   context.clickScreenButton("Back");context.clickScreenButton("Lookup");context.runOnClient(client->{var screen=(SettingsScreen)Platform.screen(client);int modifier=0;for(int bit=0;bit<12;bit++)if(new KeyEvent(InputConstants.KEY_F,0,1<<bit).hasControlDown()){modifier=1<<bit;break;}check(screen.keyPressed(new KeyEvent(InputConstants.KEY_F,0,modifier)),"Ctrl+F focuses search");check(screen.getFocused() instanceof EditBox,"search field receives focus");((EditBox)screen.getFocused()).setValue("NearFixture");check(screen.keyPressed(new KeyEvent(InputConstants.KEY_RETURN,0,0)),"Enter triggers lookup");});context.waitTicks(5);
   context.runOnClient(client->{Platform.screen(client).onClose();NearestProfile.key.setKey(NearestProfile.key.getDefaultKey().getType().getOrCreate(InputConstants.KEY_F9));try{KeyMapping.class.getMethod("resetMapping").invoke(null);}catch(NoSuchMethodException ignored){}catch(Exception e){throw new AssertionError(e);}KeyMapping.click(NearestProfile.key.getDefaultKey().getType().getOrCreate(InputConstants.KEY_F9));});context.waitFor(client->Platform.screen(client) instanceof SettingsScreen screen&&screen.page==3);context.runOnClient(client->{check(((SettingsScreen)Platform.screen(client)).drawLabels().stream().anyMatch(l->l.text().getString().contains("FarFixture")),"rebound key selects currently nearest player");NearestProfile.key.setKey(NearestProfile.key.getDefaultKey());try{KeyMapping.class.getMethod("resetMapping").invoke(null);}catch(NoSuchMethodException ignored){}catch(Exception e){throw new AssertionError(e);}});
   context.runOnClient(client->{Platform.screen(client).onClose();var chat=new net.minecraft.client.gui.screens.ChatScreen("",false);client.setScreenAndShow(chat);press(client);});context.waitTicks(3);context.runOnClient(client->{check(Platform.screen(client) instanceof net.minecraft.client.gui.screens.ChatScreen,"P in chat is not a hotkey");client.setScreenAndShow(null);});context.waitTicks(3);context.runOnClient(client->check(Platform.screen(client)==null,"ignored P is not queued after chat closes"));
   context.runOnClient(client->{for(var player:players)client.level.removeEntity(player.getId(),net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);check(NearestProfile.nearest(client).isEmpty(),"no other loaded players returns empty");press(client);});context.waitTicks(3);context.runOnClient(client->check(Platform.screen(client)==null,"P with no player does not open empty profile"));
   mismatch.set(true);try(var wrong=new MinecraftIdentityResolver(base)){context.runOnClient(client->{RestrictionChecks.identities=wrong;requests.set(0);var screen=new SettingsScreen(null);client.setScreenAndShow(screen);screen.openNearestProfile(new NearestProfile.Target(near,"WrongFixture",7));});context.waitFor(client->((SettingsScreen)Platform.screen(client)).drawLabels().stream().anyMatch(l->l.text().getString().contains("does not match")));context.runOnClient(client->check(requests.get()==0,"UUID mismatch sends no provider requests"));}
   mismatch.set(false);try(var fresh=new MinecraftIdentityResolver(base)){context.runOnClient(client->{RestrictionChecks.identities=fresh;requests.set(0);var screen=new SettingsScreen(null);client.setScreenAndShow(screen);screen.openNearestProfile(new NearestProfile.Target(near,"CloseFixture",9));screen.onClose();});context.waitTicks(15);context.runOnClient(client->{check(Platform.screen(client)==null,"late identity result does not reopen closed profile");check(requests.get()==0,"closing during identity resolution prevents obsolete provider requests");});}
   context.runOnClient(client->{TierTagger.config.enabled=true;TierTagger.ranks=new ProviderRegistry(List.of(new RankingProvider(){public String id(){return "mctiers";}public Optional<String> tier(UUID id,String mode){return Optional.empty();}public boolean resolved(UUID id){return true;}public void request(UUID id){}public String status(){return "Connected";}public void clear(){}public void close(){}}));var screen=new SettingsScreen(null);client.setScreenAndShow(screen);check(screen.drawLabels().stream().anyMatch(l->l.text().getString().startsWith("No rank")),"preview explains verified missing ranks");check(!screen.previewComponent(false).getString().contains("No rank"),"missing-rank help never becomes a name-tag placeholder");});context.waitTicks(3);context.takeScreenshot("missing-rank-preview");
  }finally{server.stop(0);context.runOnClient(client->{for(var id:List.of(near,far,fake))infos(client).remove(id);for(var player:players)if(player!=null&&!player.isRemoved())client.level.removeEntity(player.getId(),net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);client.keyboardHandler.setClipboard(clipboard[0]);RestrictionChecks.identities=oldResolver;TierTagger.ranks=oldRanks;TierTagger.config=oldConfig;});}
 }
}
